const createGoal = async () => {
  if (!tenantId.value) {
    alert('Tenant ID not found. Please log in again.');
    return
  }
  
  isSavingGoal.value = true;
  
  try {
    const payload = {
      ...newGoal.value,
      type: selectedGoalType.value,
      tenant_id: tenantId.value
    };
    
    // Check if we're editing (has id) or creating new
    if (newGoal.value.id) {
      // Update existing goal
      await axios.put(`${BASE_URL$1}/goals/${newGoal.value.id}`, payload);
      alert('Goal updated successfully!');
    } else {
      // Create new goal
      await axios.post(`${BASE_URL$1}/goals`, payload);
      alert('Goal created successfully!');
    }
    
    showGoalModal.value = false;
    await fetchGoals();
  } catch (err) {
    console.error('Error saving goal:', err);
    alert('Failed to save goal: ' + (err.response?.data?.detail || err.message));
  } finally {
    isSavingGoal.value = false;
  }
};

